from pathlib import Path
import base64
import io
import re
import zipfile

PAYLOAD = ''

print("=== DASHBOARD SGSI LIVE V72 ===")

raw = base64.b64decode(PAYLOAD)
with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
    for member in zf.infolist():
        if member.is_dir():
            continue
        name = member.filename.replace("\\", "/")
        data = zf.read(member)

        if name.startswith("_source/"):
            dest = Path("imports") / Path(name).name
            dest.parent.mkdir(parents=True, exist_ok=True)
            if not dest.exists():
                dest.write_bytes(data)
                print("OK:", dest)
            else:
                print("EXISTE:", dest)
            continue

        dest = Path(name)
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists():
            backup = dest.with_name(dest.name + ".before_dashboard_live_v72.bak")
            if not backup.exists():
                backup.write_bytes(dest.read_bytes())
        dest.write_bytes(data)
        print("OK:", dest)

settings_candidates = [Path("config/settings/base.py"), Path("config/settings.py")]
settings = next((p for p in settings_candidates if p.exists()), None)
if settings is None:
    raise SystemExit("ERROR: no se encontró settings.")

text = settings.read_text(encoding="utf-8")
app_ref = '"apps.dashboard_live.apps.DashboardLiveConfig",'
if app_ref not in text:
    anchors = [
        '"apps.dashboard.apps.DashboardConfig",',
        '"apps.organization.apps.OrganizationConfig",',
        '"apps.context42.apps.Context42Config",',
    ]
    anchor = next((item for item in anchors if item in text), None)
    if anchor:
        text = text.replace(anchor, anchor + "\n    " + app_ref, 1)
    else:
        match = re.search(r"INSTALLED_APPS\s*=\s*\[\s*\n", text)
        if not match:
            raise SystemExit("ERROR: no se pudo ubicar INSTALLED_APPS.")
        pos = match.end()
        text = text[:pos] + "    " + app_ref + "\n" + text[pos:]
    settings.write_text(text, encoding="utf-8")
    print("OK: DashboardLiveConfig registrado")
else:
    print("OK: DashboardLiveConfig ya registrado")

urls = Path("config/urls.py")
if not urls.exists():
    raise SystemExit("ERROR: no existe config/urls.py")

url_text = urls.read_text(encoding="utf-8")
if 'include("apps.dashboard_live.urls")' not in url_text:
    match = re.search(r"urlpatterns\s*=\s*\[\s*\n", url_text)
    if not match:
        raise SystemExit("ERROR: no se encontró urlpatterns.")
    pos = match.end()
    url_text = url_text[:pos] + '    path("", include("apps.dashboard_live.urls")),\n' + url_text[pos:]
    urls.write_text(url_text, encoding="utf-8")
    print("OK: Dashboard SGSI Live quedó como vista principal /.")
else:
    print("OK: rutas Dashboard Live ya registradas")

print("")
print("V72 instalada.")
print("Incluye Dashboard SGSI editable, matrices OEE/OSI y RyEPI/OSI, MEFI, MEFE, EFI/EFE, trazabilidad, historial y exportación del Excel actualizado.")
print("")
print("Siguiente:")
print(r"python -m py_compile apps\dashboard_live\models.py apps\dashboard_live\forms.py apps\dashboard_live\excel_io.py apps\dashboard_live\logic.py apps\dashboard_live\importer.py apps\dashboard_live\selectors.py apps\dashboard_live\exporter.py apps\dashboard_live\change_log.py apps\dashboard_live\views.py apps\dashboard_live\urls.py apps\dashboard_live\signals.py")
